/* Personalized astrology and numerology curriculum. Educational tradition, not scientific diagnosis or prediction. */
(() => {
  "use strict";
  const planets = {
    Sun:["identity, vitality, purpose and the part of self that wants to develop","creative confidence, coherence and healthy visibility","over-identifying with achievement, pride or the need to be central","Where do I feel most alive when I am not performing for anyone?"],
    Moon:["emotional needs, instinct, memory, comfort and habitual responses","emotional literacy, care, adaptability and self-soothing","reactivity, avoidance, mood-driven choices or expecting others to guess needs","What helps me feel safe, and which needs can I meet directly?"],
    Mercury:["thinking, language, learning, perception and everyday exchange","curiosity, clear communication, analysis and flexible thinking","overthinking, scattered attention, sharp words or mistaking assumptions for facts","How do I gather information and check that I understood someone?"],
    Venus:["affection, attraction, pleasure, values, aesthetics and relating","reciprocity, discernment, warmth and the ability to enjoy","people-pleasing, idealization, avoidance of conflict or confusing approval with love","What do I value even when nobody rewards me for it?"],
    Mars:["action, desire, initiative, courage, anger and how boundaries are asserted","healthy agency, directness, stamina and constructive courage","impulsivity, resentment, aggression, passivity or chronic overextension","How can I act directly without turning every obstacle into a fight?"],
    Jupiter:["growth, meaning, faith, learning, generosity and the urge to explore","hope, perspective, mentorship and ethical confidence","excess, overpromising, moral certainty or assuming optimism replaces planning","Where does growth need both openness and good judgment?"],
    Saturn:["time, responsibility, limits, structure, commitment and earned mastery","patience, reliability, craft, boundaries and sustainable achievement","fear, rigidity, shame, perfectionism or treating rest as failure","Which skill or boundary becomes stronger through steady practice?"],
    Uranus:["freedom, disruption, experimentation, independence and collective change","originality, innovation and courage to question stale rules","contrarianism, needless disruption, detachment or change without a plan","What deserves reinvention, and what deserves consistency?"],
    Neptune:["imagination, ideals, compassion, spirituality, dreams and porous boundaries","artistic sensitivity, empathy, inspiration and symbolic imagination","confusion, projection, escapism, blurred agreements or idealizing people","Where do I need both compassion and clear evidence?"],
    Pluto:["power, control, compulsion, crisis, endings and profound transformation","honesty about difficult material, resilience and deep change","control struggles, fixation, secrecy or treating intensity as proof","What pattern am I ready to stop feeding?"]
  };
  const signs = {
    Aries:["cardinal fire","initiative, candor, speed and competitive energy","impatience, reactivity and starting before considering consequences","Practise pausing long enough to choose the right first move."],
    Taurus:["fixed earth","steadiness, patience, sensory grounding and persistence","stubbornness, possessiveness and staying too long with the familiar","Distinguish genuine stability from fear of change."],
    Gemini:["mutable air","curiosity, language, comparison and connecting ideas","scattered focus, nervous overactivity and staying at the surface","Give curiosity a structure so insight can deepen."],
    Cancer:["cardinal water","care, memory, protection and emotional attunement","defensiveness, indirectness and retreating instead of naming needs","State the need clearly while respecting other people's boundaries."],
    Leo:["fixed fire","creative warmth, loyalty, play and generous visibility","pride, validation-seeking and difficulty sharing the spotlight","Create from joy, not only for applause."],
    Virgo:["mutable earth","discernment, craft, service and attention to detail","perfectionism, worry and confusing criticism with usefulness","Let improvement be practical rather than punitive."],
    Libra:["cardinal air","fairness, dialogue, proportion and partnership","indecision, conflict avoidance and over-reliance on approval","Make a clear choice while staying open to another perspective."],
    Scorpio:["fixed water","depth, loyalty, focus and emotional courage","suspicion, control, all-or-nothing thinking and secrecy","Use honesty and boundaries instead of tests or power games."],
    Sagittarius:["mutable fire","exploration, candor, philosophy and meaning","restlessness, bluntness and certainty without enough evidence","Keep wonder alive while checking the facts."],
    Capricorn:["cardinal earth","planning, responsibility, endurance and long-range goals","overwork, pessimism and measuring worth by productivity","Build success that leaves room for relationships and rest."],
    Aquarius:["fixed air","independence, systems thinking, experimentation and community","detachment, contrarianism and treating feelings as irrelevant data","Pair intellectual freedom with emotional presence."],
    Pisces:["mutable water","imagination, empathy, symbolism and permeability","idealization, avoidance, porous boundaries and unclear expectations","Protect sensitivity with clear agreements and grounded routines."]
  };
  const houses = {
    1:["identity, body, first impressions and approach to life","How you enter situations, initiate, and present yourself before people know you."],
    2:["income, possessions, resources, skills and self-worth","How you earn, preserve, spend and define what is valuable or secure."],
    3:["communication, siblings, neighbors, local travel and early learning","How you think aloud, ask questions, exchange information and move through your immediate environment."],
    4:["home, family, roots, ancestry and private foundations","What belonging means, how you rest, and the emotional base from which you live."],
    5:["creativity, pleasure, romance, play, children and self-expression","How you create for its own sake, take healthy risks and make room for delight."],
    6:["daily work, routines, service, maintenance and health practices","How you organize ordinary life, care for the body and make useful contributions."],
    7:["committed partnership, contracts, clients and open one-to-one relationships","What you seek in equals, how you negotiate, and what you learn through partnership."],
    8:["shared resources, debt, taxes, inheritance, intimacy, trust and endings","How you handle dependence, vulnerability, shared power and major transitions."],
    9:["higher education, philosophy, religion, law, publishing and long journeys","How you build a worldview, test beliefs and encounter unfamiliar cultures or ideas."],
    10:["career, public role, reputation, authority and visible contribution","What you aim to build publicly and how you relate to responsibility or recognition."],
    11:["friends, groups, networks, patrons, collective projects and future hopes","How you participate in communities and turn ideals into shared plans."],
    12:["solitude, retreat, hidden matters, institutions, dreams and endings","What happens outside public view, where you need restoration, and what you may avoid seeing."]
  };
  const aspects = [
    ["Conjunction (0°)","Two planetary functions occupy the same region and operate together. The result depends on the planets involved, their condition and context; it is not automatically good or bad."],
    ["Sextile (60°)","A traditional opportunity aspect associated with cooperation that usually needs participation. It can describe a resource that becomes useful when deliberately developed."],
    ["Square (90°)","A friction aspect in traditional astrology. It can describe competing needs, pressure or a skill developed through action. It does not mean inevitable conflict."],
    ["Trine (120°)","A traditional ease aspect associated with flow and shared element. Ease can become a strength, but it can also be taken for granted."],
    ["Opposition (180°)","An axis of polarity that can feel like competing priorities or projection onto others. Integration means recognizing both sides rather than choosing a permanent winner."],
    ["Quincunx (150°)","A modern interpretive aspect often used for adjustment between functions that do not share an obvious rhythm. Its use and orb vary by school."],
    ["Semisextile (30°)","A minor aspect sometimes interpreted as subtle neighboring-sign adjustment. Many astrologers give it little weight unless strongly repeated."]
  ];
  const numerology = [
    ["Life Path","Calculated from the birth date; a broad symbolic theme for development, not a fixed destiny."],
    ["Expression / Destiny","Calculated from all letters in the full birth name using a chosen letter-number system; describes the talents or style associated with the name in that tradition."],
    ["Soul Urge","Calculated from vowels in the full birth name; used as a symbol for inner motivation and desire."],
    ["Personality","Calculated from consonants in the full birth name; used as a symbolic description of the outward style others may notice."],
    ["Personal Year","A cycle number derived from birth month/day and the calendar year; traditions use it as a reflective annual theme, not a forecast."],
    ["Personal Month and Day","Shorter cycle calculations used as journaling prompts. They should never override practical judgment or real-world evidence."]
  ];
  const topics = [
    {id:"chart-foundations",title:"1. Birth-chart foundations",summary:"What a natal chart is, how it is calculated, and how to read it without flattening it into a Sun-sign description.",lessons:[
      {title:"What a natal chart actually shows",body:["A natal chart is a symbolic map of where the Sun, Moon and selected planets appeared from a particular place at a particular time. The zodiac positions are calculated from astronomical coordinates; the meanings attached to them belong to astrological traditions.","A chart is not a personality test with one correct answer. It is a layered interpretive language: planets describe functions, signs describe styles, houses describe life areas, and aspects describe angular relationships between functions.","A birth time matters because the Ascendant and house cusps move quickly. If the time is missing or uncertain, rising sign and house interpretations should be marked unknown or approximate rather than guessed."],example:"Read one placement as a sentence: Venus (values and relating) in a sign (style) in a house (life area), modified by its closest aspects.",quiz:[["Which information is needed to calculate an Ascendant reliably?",["Birth date only","Birth date, accurate time and location","Sun sign and current city"],1,"The horizon angle depends on time and geographic location."],["What is the usual interpretive order?",["House, then horoscope, then fate","Planet, sign, house, aspects","Sun sign only"],1,"Planet = function, sign = style, house = life area, aspects = relationships between functions."]]},
      {title:"The four layers: planet, sign, house and aspect",body:["The planet tells you what psychological or symbolic function is being discussed: for example, Mercury is associated with thought and communication, while Saturn is associated with limits, time and responsibility.","The sign describes the style through which the function is expressed. Mars in Aries and Mars in Taurus are both about action and assertion, but the traditional sign symbolism gives them different tempos and approaches.","The house locates the theme in a field of life, while aspects show how that planet relates to other chart factors. Never interpret a placement from only one of these layers if the rest of the chart is available."],example:"A planet in the 4th house is interpreted through home, roots and private foundations; its sign describes the manner, and its aspects add supportive or tense relationships.",quiz:[["A planet represents…",["A life department","A symbolic function","A fixed personality label"],1,"Planets describe functions such as relating, thinking, acting or structuring."],["A house represents…",["A life area","A planet's speed","A person's age"],0,"Houses organize the chart into life areas."]]},
      {title:"Chart accuracy, house systems and responsible interpretation",body:["The Ascendant is the sign rising on the eastern horizon at the birth moment. The Midheaven is the highest point of the ecliptic in the chart and is commonly linked with public direction and vocation. Both depend on time and location.","House systems divide the chart in different ways. Placidus is common in modern Western astrology; Whole Sign assigns one entire sign to each house from the rising sign. A house placement can change when the system changes, so an app should name the system it uses.","Astrological interpretation is a cultural and symbolic practice, not an empirically validated method for diagnosing mental health, predicting events or deciding whether someone is trustworthy. Use it for reflection, not as a substitute for evidence or professional advice."],example:"If a birth time is approximate, read planets by sign confidently only to the degree precision available, and mark the Ascendant and houses as uncertain.",quiz:[["Why name the house system?",["It can change house placements","It changes the birth date","It proves astrology"],0,"Different house systems divide chart space differently."],["What is a responsible use of astrology?",["Diagnose a person","Replace evidence in decisions","Use symbols as reflection prompts"],2,"Astrology should not be treated as a scientific diagnosis or prediction system."]]}
    ]},
    {id:"planets",title:"2. The planets and chart points",summary:"Understand every classical and modern planet, the Sun and Moon, and the angles. Each placement in your own chart receives a separate interpretation.",lessons:[
      {title:"The personal planets: Sun, Moon, Mercury, Venus and Mars",body:["The Sun symbolizes vitality, identity and the process of becoming more fully oneself. The Moon symbolizes needs, instinct, memory and patterns of emotional regulation. Neither one alone describes a whole person.","Mercury symbolizes thinking, language, learning and exchange. Venus symbolizes values, attraction, pleasure and relating. Mars symbolizes desire, initiative, anger and the way energy is directed.","These are called personal planets because they move relatively quickly and are often used to describe immediate habits and interpersonal style. Their sign, house and aspects add the specific context."],example:"In a chart reading, ask what the person needs (Moon), how they communicate (Mercury), how they relate (Venus), and how they act or set boundaries (Mars).",quiz:[["Which planet is most directly associated with communication?",["Venus","Mercury","Saturn"],1,"Mercury is the traditional significator of thought, speech and exchange."],["Which pair is most associated with desire and relating?",["Venus and Mars","Saturn and Neptune","Uranus and Pluto"],0,"Venus is associated with attraction and values; Mars with desire and action."]]},
      {title:"The social planets: Jupiter and Saturn",body:["Jupiter symbolizes expansion, meaning, education, generosity and confidence. In a chart, it can show where someone seeks growth or may benefit from perspective. Its shadow is excess, overconfidence or promising more than can be delivered.","Saturn symbolizes structure, responsibility, time, boundaries and mastery through practice. It can describe where a person meets limits and builds competence gradually. Its shadow can include fear, rigidity and harsh self-judgment.","Jupiter and Saturn are often read together as an expansion-and-consolidation pair: growth needs discernment, while structure needs a reason to exist. A balanced interpretation considers both opportunity and responsibility."],example:"Jupiter may invite learning; Saturn asks what routine, cost and commitment will make that learning sustainable.",quiz:[["Jupiter is commonly associated with…",["Expansion and meaning","Boundaries and delay","Sudden disruption"],0,"Jupiter traditionally signifies growth, wisdom and abundance, including the risk of excess."],["Saturn's constructive expression is…",["Avoiding every limit","Mastery through practice","Instant reward"],1,"Saturn is associated with time, structure and earned skill."]]},
      {title:"The outer planets and chart angles",body:["Uranus is used in modern astrology for disruption, freedom and innovation; Neptune for imagination, ideals and blurred boundaries; Pluto for power, compulsion and deep transformation. These are slow-moving planets, so their sign placements describe generations as well as individuals.","Their house placements and close aspects are more personal than sign alone. A generation shares broad outer-planet sign placements, while the house and exact contacts help describe how those themes are symbolically located in an individual's chart.","The Ascendant describes the eastern horizon and is commonly read as approach, presentation and embodied style. The Midheaven is linked with public role, vocation and visibility. The Descendant and Imum Coeli form the relationship and home axes opposite the Ascendant and Midheaven."],example:"Do not say everyone with Pluto in the same sign has the same personality. Check the house, close aspects and personal-planet contacts.",quiz:[["Why are outer-planet sign placements less individually distinctive?",["They move slowly and are shared by generations","They are not calculated","They replace the Sun"],0,"Uranus, Neptune and Pluto stay in a sign for years, so house and aspects add personal context."],["The Ascendant is…",["The eastern horizon at birth","The planet closest to Earth","The same as the Sun sign"],0,"The Ascendant is the rising point and depends on exact time and place."]]}
    ]},
    {id:"signs",title:"3. The twelve zodiac signs",summary:"Learn the elements, modalities, strengths, shadow expressions and practical growth work of every sign.",lessons:[
      {title:"Elements and modalities",body:["The four elements group signs by symbolic temperament: fire is associated with initiative and inspiration; earth with material reality and steadiness; air with ideas and exchange; water with feeling, memory and sensitivity.","The three modalities describe how a sign approaches change. Cardinal signs initiate, fixed signs sustain, and mutable signs adapt or transition. Each element appears in all three modalities.","An element or modality is not a scientific personality category. It is a traditional interpretive shorthand. A full chart contains many signs and planetary functions, so one element should not be used to label the whole person."],example:"Pisces is mutable water: the element suggests sensitivity and feeling, while the modality suggests adaptation and transition.",quiz:[["Which element is traditionally linked with ideas and exchange?",["Earth","Air","Water"],1,"Air signs are Gemini, Libra and Aquarius."],["Mutable signs are associated with…",["Initiating","Sustaining","Adapting"],2,"Mutable signs are Gemini, Virgo, Sagittarius and Pisces."]]},
      {title:"Aries through Virgo: the first six signs",body:["Aries is cardinal fire: initiative and directness; its growth work is pausing before acting. Taurus is fixed earth: steadiness and sensory grounding; its work is distinguishing security from resistance. Gemini is mutable air: curiosity and language; its work is sustaining focus.","Cancer is cardinal water: care and protection; its work is naming needs without retreating. Leo is fixed fire: creative warmth and visibility; its work is creating without depending on applause. Virgo is mutable earth: discernment and craft; its work is improving without perfectionism.","These are broad traditional sign themes. A planet in one of these signs expresses its own function through that sign; it does not make every part of the person identical to the sign."],example:"Mercury in Gemini and Saturn in Gemini both use Gemini symbolism, but Mercury describes thinking while Saturn describes structure and responsibility.",quiz:[["Which sign is fixed earth?",["Aries","Taurus","Gemini"],1,"Taurus is fixed earth."],["Virgo's constructive growth theme is…",["Practical improvement without perfectionism","Avoid all details","Seek constant applause"],0,"Virgo symbolism emphasizes discernment and craft; its shadow is excessive criticism."]]},
      {title:"Libra through Pisces: the final six signs",body:["Libra is cardinal air: dialogue and fairness; its work is making choices rather than living only for approval. Scorpio is fixed water: depth and focus; its work is choosing honesty over control. Sagittarius is mutable fire: exploration and meaning; its work is keeping curiosity while checking facts.","Capricorn is cardinal earth: long-range building; its work is making success sustainable. Aquarius is fixed air: independence and systems thinking; its work is combining ideas with emotional presence. Pisces is mutable water: imagination and empathy; its work is protecting sensitivity with clear boundaries.","For a sign-by-sign reading, look at which planets occupy the sign, whether the sign is on an angle or house cusp, and which aspects connect to those planets. A sign with no planets can still matter through its house and ruling planet."],example:"Pisces Sun is only one placement. The Moon, Ascendant, Mercury, Venus, Mars, houses and aspects provide essential additional context.",quiz:[["Which sign is cardinal air?",["Libra","Scorpio","Sagittarius"],0,"Libra is cardinal air."],["A sign with no natal planet…",["Never matters","Can still matter through its house and ruler","Proves a missing life area"],1,"Empty houses are interpreted through their cusp sign and ruler, among other factors."]]}
    ]},
    {id:"houses",title:"4. The twelve astrological houses",summary:"A detailed guide to each life area, its traditional topics, everyday expressions and interpretation with planets.",lessons:[
      {title:"Houses 1–4: self, resources, communication and roots",body:["The 1st house concerns the body, identity, approach and first impressions. The 2nd concerns resources, possessions, income, skills and values. Neither house alone determines appearance, wealth or worth.","The 3rd house concerns communication, siblings, neighbors, local movement and early learning. The 4th concerns home, family, roots, private foundations and ancestry. These houses describe symbolic areas, not guarantees about family events.","To interpret a planet in a house, combine the planet's function with the topics of that house and the sign on its cusp. Then check the planet's ruler and aspects."],example:"Mercury in the 3rd house might emphasize communication and learning; Mercury in the 4th might connect thought and conversation with family, memory or private life.",quiz:[["Which house is most associated with home and roots?",["2nd","4th","6th"],1,"The 4th house is traditionally associated with home, family and foundations."],["The 2nd house includes…",["Resources and values","Romantic partners only","Career reputation only"],0,"The 2nd house covers possessions, income, skills and self-worth."]]},
      {title:"Houses 5–8: creativity, work, partnership and shared resources",body:["The 5th house concerns creativity, pleasure, romance, play and children. The 6th concerns daily work, service, routines, maintenance and health practices. These are not medical predictions; they are symbolic life areas.","The 7th house concerns committed partnerships, contracts, clients and one-to-one relationships. The 8th concerns shared money, debt, taxes, inheritance, intimacy, trust, vulnerability and major transitions.","The 7th and 8th are not simply 'marriage' and 'death' houses. Their topics are broad and should be interpreted carefully, with the planets, rulers and chart context in view."],example:"Venus in the 6th can connect values and relating with daily routines or service; Venus in the 8th can make trust and shared resources important themes.",quiz:[["Which house relates to committed one-to-one partnerships?",["5th","7th","9th"],1,"The 7th house is traditionally associated with partners, contracts and open one-to-one relationships."],["The 8th house includes…",["Shared resources and intimacy","Siblings and short trips","Daily errands only"],0,"The 8th house includes shared money, vulnerability and transitions."]]},
      {title:"Houses 9–12: beliefs, vocation, community and the unseen",body:["The 9th house concerns higher learning, philosophy, religion, law, publishing and long journeys. The 10th concerns career, reputation, authority, public role and visible contribution. The Midheaven is often interpreted alongside the 10th house.","The 11th concerns friends, groups, networks, patrons, collective projects and future hopes. The 12th concerns solitude, retreat, hidden matters, dreams, institutions and restoration. Avoid turning the 12th into a simplistic label for secrets or suffering.","An empty house is not an empty life area. Read the sign on its cusp, the ruler's sign and house, and any aspects to that ruler. House systems can change house boundaries, so name the system used."],example:"A 10th-house ruler in the 4th may symbolically link public work with home, family or private foundations; it does not dictate one career.",quiz:[["Which house is linked with friends and groups?",["9th","11th","12th"],1,"The 11th house is associated with networks, friends and collective aims."],["An empty house means…",["That life area cannot happen","Read its cusp sign and ruler","It has no meaning"],1,"An empty house is interpreted through its sign, ruler and aspects."]]}
    ]},
    {id:"aspects",title:"5. Aspects, orbs and chart patterns",summary:"Understand conjunctions, sextiles, squares, trines, oppositions, minor aspects, applying/separating orbs and configurations.",lessons:[
      {title:"The five major aspects",body:["Aspects are angular relationships between chart points. The five major aspects are conjunction (0°), sextile (60°), square (90°), trine (120°) and opposition (180°). Different traditions and modern schools assign different meanings and orbs.","A conjunction blends or intensifies functions. A sextile is often read as an opportunity that needs participation. A square suggests friction or pressure. A trine suggests ease or flow. An opposition describes polarity and the need to recognize both sides.","No aspect is automatically good or bad. A trine can be underused; a square can develop skill. Interpretation depends on the planets involved, their signs and houses, closeness of the aspect and the rest of the chart."],example:"A square between Mercury and Saturn could be read as tension between spontaneous thought and caution; it may also describe disciplined study and careful speech.",quiz:[["Which major aspect is 90 degrees?",["Trine","Square","Opposition"],1,"A square is a 90-degree angular relationship."],["A trine should be interpreted as…",["Guaranteed success","Ease or flow that can be developed","Certain conflict"],1,"A trine traditionally suggests ease, not guaranteed outcomes."]]},
      {title:"Orbs, applying and separating aspects",body:["An orb is the distance from the exact aspect angle. If two points are 92° apart, their square has a 2° orb. Astrologers differ on acceptable orbs; many use wider orbs for luminaries and tighter ones for minor points.","An applying aspect is moving toward exactness; a separating aspect has passed exactness. Some traditions give applying aspects greater emphasis, but the importance of an aspect also depends on the chart and interpretive school.","The app should display the exact angle and orb used by its calculation. A close aspect is not automatically more important than every other chart factor, and a wide aspect should not be described as exact."],example:"If a natal square is 1.5° from exact, it is tighter than a square with a 7° orb; the chosen orb policy should be stated.",quiz:[["An orb measures…",["The distance from exact aspect angle","The house number","A planet's speed"],0,"Orb is the angular difference from the exact aspect."],["A separating aspect has…",["Not yet reached exactness","Passed exactness","No angle"],1,"Separating means the exact aspect has already occurred."]]},
      {title:"Aspect patterns and practical synthesis",body:["A T-square involves an opposition with a third point squaring both ends. A grand trine links three points by trines. A grand cross links four points through oppositions and squares. These patterns are meaningful only when the geometry and orbs actually qualify.","A stellium is a concentration of several planets in one sign or house; definitions vary by astrologer. It can emphasize a theme, but it does not erase the rest of the chart. Always state the rule used to count it.","When reading a pattern, identify the planets, signs, houses and exact orbs, then describe the tension or flow in neutral language. Avoid claims that a configuration guarantees trauma, fame, wealth or relationship outcomes."],example:"For a T-square, name the opposition's two competing functions and the planet at the apex; use the apex house as one possible focus for integration.",quiz:[["A T-square includes…",["One opposition and two squares","Three trines","Four conjunctions"],0,"A T-square is formed by an opposition with a third point squaring both ends."],["Why state a stellium definition?",["Astrologers count them differently","It changes the birth time","It is always three planets"],0,"The number of bodies and whether angles are included vary by school."]]}
    ]},
    {id:"chart-rulers",title:"6. Angles, chart rulers and dispositors",summary:"Learn the Ascendant, Midheaven, Descendant, IC, planetary rulers and chains of rulership.",lessons:[
      {title:"The four angles",body:["The Ascendant (ASC) is the eastern horizon and is associated in modern practice with embodiment, approach and first impressions. The Descendant (DSC) is opposite and is commonly associated with partnership and the qualities encountered in one-to-one relationships.","The Midheaven (MC) is the highest point of the ecliptic and is often read in relation to vocation, public role and reputation. The Imum Coeli (IC) is opposite and is associated with home, roots and private foundations.","Angles are sensitive to birth time and location. If the recorded time is uncertain, interpretations that depend on the angles or house cusps should be labeled uncertain."],example:"A planet close to the Ascendant may be emphasized in presentation or approach, but the exact conjunction depends on the orb and chart context.",quiz:[["The Descendant is opposite the…",["Moon","Ascendant","Midheaven"],1,"The Ascendant–Descendant axis describes self and one-to-one relating."],["The IC is commonly associated with…",["Private roots and home","Public reputation","Daily errands"],0,"The IC is opposite the Midheaven and is associated with private foundations."]]},
      {title:"Chart ruler and planetary rulership",body:["The chart ruler is usually the planet ruling the sign on the Ascendant. To interpret it, locate that planet by sign, house and aspects. It is one organizing thread, not a single planet that explains the entire person.","Traditional rulership assigns domicile rulers to signs: for example, Mars rules Aries and Scorpio; Venus rules Taurus and Libra; Mercury rules Gemini and Virgo; Jupiter rules Sagittarius and Pisces; Saturn rules Capricorn and Aquarius. Modern astrologers often assign Uranus, Neptune and Pluto as co-rulers of Aquarius, Pisces and Scorpio.","A chart can be read using traditional rulers, modern rulers or both, but the chosen system should be named. Do not silently switch systems to make an interpretation sound more certain."],example:"If the Ascendant is Libra, Venus is the traditional chart ruler; its sign, house and aspects become a useful organizing thread.",quiz:[["The chart ruler is usually…",["The ruler of the Ascendant sign","The fastest planet","Always the Sun"],0,"The chart ruler is conventionally the planet ruling the rising sign."],["Why name a rulership system?",["Traditional and modern rulerships differ","It changes the planet positions","It proves compatibility"],0,"Traditional and modern schools assign some outer-planet rulerships differently."]]},
      {title:"Dispositors and rulership chains",body:["A dispositor is the ruler of the sign a planet occupies. For example, if Mercury is in Taurus, Venus is its traditional dispositor because Venus rules Taurus. The dispositor's placement adds another layer to the interpretation.","A dispositor chain follows rulers from one planet to another. Some chains end in a planet in its own sign, sometimes called a final dispositor; other charts form loops or mutual receptions. Definitions vary, so an app should show the chain rather than invent a single answer.","Rulership is a traditional astrological technique, not a claim that one planet controls a person's behavior. Use it as a way to trace symbolic relationships between chart placements."],example:"For Venus in Aries, Mars is the traditional dispositor. Read Venus in Aries, then inspect Mars's sign, house and aspects.",quiz:[["A dispositor is…",["The ruler of the sign a planet occupies","A planet's house cusp","A daily transit"],0,"The dispositor is the ruler of the sign where the planet is placed."],["A final dispositor is commonly…",["A chain endpoint in its own sign","The newest planet discovered","Always Pluto"],0,"A final dispositor is a planet that rules its own sign and ends the chain in that method."]]}
    ]},
    {id:"chart-synthesis",title:"7. Putting a whole chart together",summary:"Move beyond isolated placements: prioritize patterns, balance contradictions and write nuanced interpretations.",lessons:[
      {title:"Start with the big picture",body:["Begin with the Sun, Moon and Ascendant if the birth time is reliable. Then look at chart ruler, personal planets, angular planets, concentrations by house or sign, and the closest major aspects. This is a practical reading order, not a universal law.","Check the chart's elements and modalities as broad patterns, but do not reduce a person to a count. A chart can contain contradictions because people have different needs in different contexts.","Separate what is calculated from what is interpreted. The degrees, signs, houses and aspects are computed; descriptions of personality and life themes are symbolic readings that should be phrased as possibilities and questions."],example:"A strong air emphasis may suggest a symbolic focus on ideas and exchange, while a water Moon may indicate that emotional needs still require care and attention.",quiz:[["What should be separated in a responsible reading?",["Computed positions and symbolic interpretation","Planets and signs only","All difficult placements"],0,"Positions are calculations; meanings are interpretive traditions."],["Why avoid one-placement conclusions?",["A chart is a layered whole","The Sun sign is always wrong","Houses are random"],0,"A whole chart combines multiple placements and relationships."]]},
      {title:"Prioritizing placements and resolving contradictions",body:["Give more attention to accurate angles, luminaries, chart ruler, angular planets and close aspects, while explaining why you prioritize them. There is no single universally accepted scoring formula for chart importance.","When two placements appear to conflict, do not force them into one label. A person can want independence in one area and closeness in another; a chart can symbolize different responses in different life contexts.","Use conditional language: 'This may show up as…', 'A useful question is…', or 'At its best… and under stress…'. Avoid declaring that someone is secretly manipulative, destined to be alone or guaranteed to succeed."],example:"Venus in Libra may symbolize cooperation while Mars in Aries symbolizes direct action. The task is not to choose one as the 'real' self but to understand when each response is useful.",quiz:[["A chart's contradictions should be…",["Ignored","Explained as different needs or contexts","Treated as proof the chart is wrong"],1,"People can have multiple, context-dependent motivations."],["Which phrasing is most responsible?",["You will definitely…","This placement proves…","One possible expression is…"],2,"Symbolic readings should not be presented as certainty."]]},
      {title:"Writing a practical personal interpretation",body:["A useful interpretation connects a placement to an everyday situation, a strength, a stress response and a practical experiment. It should be specific enough to be useful without claiming to know the person's private experience better than they do.","For each theme, ask: What is the need? What behavior might express it? What happens under pressure? What helps restore balance? What real-life evidence supports or challenges this reading?","The best use of a chart is reflective agency. A placement is not an excuse for harmful behavior, a reason to stay in an unsafe relationship or a substitute for a concrete plan."],example:"Instead of 'Saturn makes you afraid of love', try 'Saturn contacting Venus is traditionally read as caution or seriousness in relating; notice whether boundaries help you build trust or become a wall.'",quiz:[["A practical interpretation should include…",["Only a fixed label","Strength, stress pattern and an actionable reflection","A guaranteed prediction"],1,"A useful interpretation translates symbolism into reflection and choice."],["Can a chart excuse harmful behavior?",["Yes","No"],1,"Astrology does not excuse harm or replace accountability."]]}
    ]},
    {id:"life-themes",title:"8. Life themes: personality, love, work and fulfillment",summary:"A reflective framework for everyday life, private self, maturity, strengths, pitfalls and fulfillment.",lessons:[
      {title:"Personality, private self and what others see",body:["Use the Ascendant and 1st house for approach and presentation; the Sun for identity and vitality; the Moon for emotional needs and habitual comfort. These are interpretive lenses, not separate masks or objective personality measurements.","The 4th house can be used to reflect on private foundations and home; the 10th on public role and responsibility. Compare them as an axis rather than assuming the public self is fake and the private self is the only truth.","Ask what feels accurate in lived experience. If a description does not fit, treat it as a prompt to examine context or a different school of interpretation, not as proof that the person is in denial."],example:"Compare the rising sign's social approach with the Moon's private comfort needs. Ask where they cooperate and where they need different conditions.",quiz:[["Which pairing is useful for comparing public and private foundations?",["4th and 10th houses","2nd and 3rd only","Venus and Mars only"],0,"The 4th–10th axis is commonly read as private roots and public role."],["If an interpretation does not fit, you should…",["Force it","Treat it as a prompt and check lived experience","Assume the person is in denial"],1,"Astrology is interpretive; lived experience matters."]]},
      {title:"Love, maturity, downfalls and boundaries",body:["For relationship reflection, consider Venus for values and affection, Mars for desire and assertion, the Moon for emotional needs, Mercury for communication, and the 7th house for partnership themes. No single placement guarantees compatibility or relationship success.","Maturity is shown through behavior: honesty, accountability, repair after conflict, consent, emotional regulation and respect for boundaries. Astrology can prompt questions about these skills, but cannot establish whether a partner is safe or trustworthy.","A 'shadow' expression is a possible stress pattern, not a moral verdict. Translate it into a choice: name needs instead of testing people, set boundaries instead of controlling, and repair harm instead of blaming a chart placement."],example:"A Venus–Saturn contact might be explored as a wish for reliability and a fear of rejection. The mature expression is clear standards and gradual trust, not emotional withholding.",quiz:[["Which factors are useful for relationship reflection?",["Venus, Mars, Moon, Mercury and 7th house","Only the Sun sign","Only the 12th house"],0,"Relationships involve needs, values, desire, communication and partnership patterns."],["What establishes relationship safety?",["A zodiac match","Consistent behavior, consent and accountability","A synastry score"],1,"Safety is assessed through real behavior, not astrology."]]},
      {title:"Work, purpose, everyday life and fulfillment",body:["For vocation and public contribution, astrologers often examine the Midheaven, 10th house, its ruler, Saturn, the 6th house for daily work and routines, and the 2nd house for resources and skills. These symbols do not select a career for someone.","For fulfillment, compare what energizes you (Sun), what restores you (Moon), what you value (Venus), how you act (Mars), and what structures you can sustain (Saturn). A meaningful life needs both aspiration and workable daily conditions.","Translate insights into experiments: try a class, build a routine, request feedback, budget for a goal, or protect time for rest. Review what actually improves your life rather than treating an interpretation as a command."],example:"A chart may suggest interest in teaching or research, but test that through actual activities, skills, values, work conditions and opportunities.",quiz:[["Which houses are often reviewed for work and resources?",["2nd, 6th and 10th","1st only","8th only"],0,"The 2nd, 6th and 10th cover resources, daily work and public role."],["A chart-based career idea should be…",["Treated as destiny","Tested through real-world experiments","Used instead of skills"],1,"Career choices need evidence, skills, constraints and experience."]]}
    ]},
    {id:"compatibility",title:"9. Compatibility and relationship dynamics",summary:"All twelve signs, their relational strengths and stress patterns, and how to compare two complete charts responsibly.",lessons:[
      {title:"Compatibility is more than Sun signs",body:["A Sun-sign pairing is a tiny slice of compatibility. A fuller astrological comparison (synastry) examines both charts, including Moon, Mercury, Venus, Mars, Ascendant/Descendant, Saturn and aspects between one person's planets and the other's.","Composite charts are a separate technique that creates a midpoint chart for a relationship. It should not be confused with synastry. Both are symbolic methods, and neither can tell you whether a relationship will be healthy or last.","Real compatibility depends on values, communication, mutual respect, attraction, shared goals, emotional safety, consent, reliability and how people repair conflict. Astrology can suggest conversation topics, not make the decision."],example:"Two people with challenging synastry can build a respectful relationship; an apparently harmonious chart cannot compensate for dishonesty or coercion.",quiz:[["Synastry compares…",["Two natal charts and their cross-aspects","Only one person's Sun","A daily horoscope"],0,"Synastry examines relationships between two charts."],["What matters most for actual relationship safety?",["Astrological harmony","Consent, behavior and respect","Matching elements"],1,"Astrology cannot establish safety or trustworthiness."]]},
      {title:"The twelve signs in relationships: strengths and stress patterns",body:["Aries can bring directness and initiative; under stress it may rush or become reactive. Taurus can bring steadiness and loyalty; under stress it may resist change. Gemini can bring curiosity and conversation; under stress it may scatter attention or avoid depth.","Cancer can bring care and emotional attunement; under stress it may withdraw or become defensive. Leo can bring warmth and generosity; under stress it may seek constant validation. Virgo can bring practical care and discernment; under stress it may criticize or over-manage.","Libra can bring fairness and dialogue; under stress it may avoid decisions. Scorpio can bring loyalty and depth; under stress it may become suspicious or controlling. Sagittarius can bring optimism and exploration; under stress it may be blunt or restless.","Capricorn can bring reliability and long-range planning; under stress it may overwork or become guarded. Aquarius can bring independence and open-mindedness; under stress it may detach. Pisces can bring empathy and imagination; under stress it may idealize or blur boundaries.","These are broad sign archetypes, not facts about every person. To understand a real partner, ask them directly about needs, conflict, affection, independence and commitments."],example:"For each sign, describe both its generous expression and a stress pattern, then ask what helps that person return to their best behavior.",quiz:[["A balanced sign guide should include…",["Only positive traits","Strengths and possible stress patterns","A fixed score"],1,"Balanced interpretation avoids idealizing or demonizing a sign."],["How should you confirm a partner's needs?",["Assume from their sign","Ask and observe their behavior","Use a compatibility ranking"],1,"The person is the authority on their own needs."]]},
      {title:"How to love well, repair conflict and compare charts",body:["A useful relationship guide describes communication preferences, emotional needs, affection, autonomy and likely friction points as questions to explore. It does not claim that every person of a sign wants the same kind of love.","When comparing charts, note exact cross-aspects and house overlays, state the orb rules and avoid deterministic labels such as soulmate, toxic match or destined breakup. Include supportive and challenging contacts and what practical skills could help.","A healthy relationship is not defined by a chart. Look for mutual consent, freedom to say no, honesty, accountability, emotional and physical safety, shared effort and the ability to repair harm."],example:"A Moon–Saturn contact between charts may prompt a conversation about reassurance, responsibility and emotional availability; it does not prove coldness.",quiz:[["What is a responsible synastry interpretation?",["A guaranteed relationship forecast","A set of themes to discuss alongside real behavior","A verdict on whether to stay"],1,"Synastry is symbolic reflection, not a relationship verdict."],["What should a compatibility report never replace?",["Communication and consent","A list of aspects","An explanation of houses"],0,"Communication, consent and real-world safety always take priority."]]}
    ]},
    {id:"transits",title:"10. Transits, retrogrades and life cycles",summary:"Understand current planetary motion, natal contacts, retrograde symbolism and longer developmental cycles without deterministic forecasting.",lessons:[
      {title:"What a transit is",body:["A transit compares a planet's current position with a point in a natal chart. A transit report should identify the moving planet, natal point, aspect angle, orb, date and whether the aspect is applying or separating.","Fast-moving transits, such as the Moon, change quickly; slower planets can remain within an orb for weeks, months or longer. The same transit may be experienced differently depending on the natal planet, house and actual life context.","A transit is not proof that an event will happen. Use it to frame a reflection about timing, attention or choices, then check real circumstances."],example:"A transiting Saturn square natal Venus can be used as a prompt to review relationship commitments, money boundaries or values; it does not predict a breakup.",quiz:[["A transit compares…",["Current planetary positions with natal chart points","Two tarot cards","Only the Sun sign"],0,"Transits are current positions in relation to a natal chart."],["A transit should be presented as…",["A guaranteed event","A reflective timing theme","A medical forecast"],1,"Transits do not establish future events or diagnoses."]]},
      {title:"Retrogrades, stations and apparent motion",body:["A planet is retrograde when it appears, from Earth's viewpoint, to move backward against the background stars. This is an apparent motion caused by relative orbital motion, not a planet physically reversing its orbit.","Astrological traditions often interpret retrogrades as periods for review, reconsideration or inward attention. The meaning varies by planet and school; it is not a reason to assume that technology, relationships or plans will fail.","A station occurs when the planet appears to slow near the point where its apparent direction changes. The exact astronomy and the symbolic interpretation should be kept separate in explanations."],example:"Mercury retrograde can be used as a reminder to review messages and plans, but important decisions should be based on evidence and practical checks.",quiz:[["Retrograde motion is…",["A planet physically reversing its orbit","Apparent backward motion from Earth's viewpoint","A planet stopping"],1,"Retrograde is an apparent motion caused by relative orbital movement."],["Should retrograde periods be treated as guaranteed bad luck?",["Yes","No"],1,"Retrograde interpretations are symbolic, not reliable event forecasts."]]},
      {title:"Saturn cycles, Jupiter cycles and long-term reflection",body:["Astrologers often discuss the Saturn return around the late twenties and again later in life, when transiting Saturn returns near its natal position. Exact timing varies with retrograde motion and birth chart degree. It is a symbolic milestone, not a universal crisis.","Jupiter returns roughly every twelve years and are traditionally associated with growth, learning and opportunity. Other cycles include nodal returns and outer-planet transits, each with different timing and interpretive traditions.","Use life cycles as structured review points: What responsibilities have changed? What skills are ready to deepen? Which commitments still fit? What evidence shows that a direction is working? Avoid assuming that age alone determines a life event."],example:"Around a Saturn return, a practical review might cover work, commitments, boundaries, money and long-term goals, regardless of whether a dramatic event occurs.",quiz:[["A Saturn return occurs when…",["Saturn returns near its natal position","The Sun changes signs","The Moon is full"],0,"A Saturn return is the transit of Saturn back to its natal chart position."],["A life-cycle reading should…",["Predict a crisis","Prompt grounded review of commitments and goals","Override personal choice"],1,"Astrological cycles are best used as reflection frameworks."]]}
    ]},
    {id:"numerology",title:"11. Numerology and the astrology connection",summary:"Learn the calculation methods and meanings of Life Path, Expression, Soul Urge, Personality and personal cycles.",lessons:[
      {title:"Pythagorean letter-number mapping",body:["In the common Pythagorean method, letters cycle from 1 through 9: A=1, B=2 and so on, with I=9, J=1. Vowels and consonants may be separated for different name-based calculations.","Numerology systems vary. Chaldean numerology uses a different letter mapping and interpretive tradition. A report must name the system, explain which name is used, and show the arithmetic so the result can be checked.","Master numbers 11, 22 and sometimes 33 are treated differently by different schools. Some preserve them at intermediate stages; others reduce them. The app should show its reduction rule instead of presenting one method as universal."],example:"Show the letter values and total before reducing. If the method preserves 11, 22 or 33, state exactly where that rule applies.",quiz:[["Why should a numerology report name its method?",["Letter mappings and reduction rules vary","All systems give identical results","It changes astrology"],0,"Pythagorean and Chaldean methods use different mappings."],["A transparent calculation should show…",["Only the final number","The inputs, mapping and reduction steps","A prediction"],1,"Showing the arithmetic lets users verify the result."]]},
      {title:"Core name and birth-date numbers",body:["Life Path is commonly calculated from the birth date and used as a broad symbolic theme. Expression (sometimes called Destiny) is calculated from all letters of the full name in a selected system. Soul Urge uses vowels; Personality uses consonants.","Name-based numbers depend on the exact name convention: birth name, current name, accents, compound names and transliteration can change results. The app should let the user see and edit the source name and never silently substitute a nickname.","Interpretations of numbers 1–9 and master numbers are traditional symbolic meanings. They are not validated measures of intelligence, compatibility, character or future success."],example:"A numerology page should display the full calculation path and clearly label whether it used the saved birth name or a chosen current name.",quiz:[["The Life Path number is commonly based on…",["Birth date","Current mood","Favorite tarot card"],0,"Life Path is derived from the date of birth."],["Soul Urge is commonly calculated from…",["Consonants","Vowels","House cusps"],1,"The common Pythagorean Soul Urge calculation uses vowels in the selected name."]]},
      {title:"Personal cycles and combining systems carefully",body:["Personal Year, Month and Day numbers are calculated from birth-date components and the current calendar date according to a stated numerology method. They are used as reflective themes, not event predictions.","Astrology and numerology are separate symbolic systems with different histories and calculations. An app can place their themes side by side, but should not claim that one mathematically proves the other.","A useful journal prompt asks how a cycle theme relates to current priorities, relationships, energy and practical commitments. Users should be free to disagree with an interpretation and record their own meaning."],example:"If a personal-day theme suggests organization, turn it into one realistic task rather than expecting the day to unfold in a particular way.",quiz:[["A personal-day number should be used as…",["A guaranteed forecast","A reflection prompt","A substitute for planning"],1,"Personal cycles are symbolic prompts, not predictions."],["Astrology and numerology are…",["The same calculation system","Separate symbolic systems","Scientifically proven predictors"],1,"They have distinct methods and traditions."]]}
    ]},
    {id:"practice-and-ethics",title:"12. Reading practice, evidence and ethical use",summary:"Build a repeatable method, check sources, avoid confirmation bias and use the chart without surrendering agency.",lessons:[
      {title:"A repeatable chart-reading method",body:["Start by confirming birth data, time accuracy, zodiac and house system. List the placements and aspects actually present. Mark unknown or approximate information before interpreting.","Choose a focus question, identify the relevant planets and houses, then combine planet, sign, house, ruler and close aspects. Write one possible strength, one stress expression and one practical question for each theme.","Finish by checking the interpretation against lived experience and alternative explanations. Keep a record of what was useful, what did not fit and what you learned. This is more honest than remembering only apparent hits."],example:"For a question about work routines, begin with the 6th house, its ruler and relevant planets; include the 10th for public direction and 2nd for resources if relevant.",quiz:[["What comes first in a careful reading?",["Confirm data and calculation settings","Pick a prediction","Choose the most dramatic placement"],0,"Data quality and settings determine what can be interpreted."],["Why record what does not fit?",["To reduce confirmation bias","To force agreement","To make the chart more dramatic"],0,"Recording misses as well as hits helps keep interpretation honest."]]},
      {title:"Sources, traditions and scientific evidence",body:["Western astrology includes multiple historical layers: Hellenistic, medieval, Renaissance and modern psychological approaches. Their techniques and meanings are not identical. A source label should identify the tradition rather than imply one universal astrology.","Astronomy can calculate planetary positions precisely; that does not validate personality or prediction claims. Controlled tests have not established astrology as a reliable scientific method for matching charts to personality or forecasting individual outcomes.","Use primary texts for historical claims, reputable astronomy references for calculations, and peer-reviewed research for empirical claims. Mark whether a source was read in full, partly reviewed or merely listed."],example:"A planet's longitude is a calculated astronomical value; the statement that it symbolizes ambition is an astrological interpretation, not an astronomical finding.",quiz:[["Astronomical calculation establishes…",["The planet's position","A personality trait","A future event"],0,"Astronomy calculates positions; symbolic meaning is a separate interpretive claim."],["A source label should…",["Distinguish read from partly read sources","Make every claim sound certain","Replace citations"],0,"Transparent source status helps readers judge claims."]]},
      {title:"Agency, consent and safe reflection",body:["Never use astrology or numerology to diagnose someone, predict violence, determine whether a person is trustworthy, or pressure someone into a relationship. These systems cannot replace direct communication, professional care or evidence.","Compatibility should never be used to excuse coercion, jealousy, disrespect, manipulation or abuse. A supposedly difficult chart does not make harmful behavior inevitable, and a supposedly harmonious chart does not make a relationship safe.","The user remains the authority on their own experience. The app should offer options, context and reflection prompts, preserve privacy and make it easy to correct birth data or disagree with a reading."],example:"If a chart suggests a boundary theme, translate it into a concrete question: 'What agreement would help me feel respected?' rather than 'This person is controlling because of their Mars.'",quiz:[["Can a chart determine whether someone is safe?",["Yes","No"],1,"Safety is assessed from behavior, consent and evidence."],["What is the user's role in interpreting a chart?",["Accept every statement","Remain the authority on their lived experience","Let the chart decide"],1,"Interpretations should support agency, not replace it."]]}
    ]}
  ];

  const sources = [
    {title:"OpenStax Astronomy 2e · Astrology and Astronomy",url:"https://openstax.org/books/astronomy-2e/pages/2-3-astrology-and-astronomy",note:"Astronomical background and the distinction between astrology, astronomy, tropical signs and constellations."},
    {title:"Claudius Ptolemy · Tetrabiblos",url:"https://sacred-texts.com/astro/ptb/",note:"Historical primary source for Hellenistic planetary, sign, aspect and triplicity doctrine. It documents a tradition; it is not modern scientific evidence."},
    {title:"William Lilly · Christian Astrology (1647)",url:"https://www.astro.com/astrology/in_lilly_e.htm",note:"Historical source for traditional house significations and horary practice."},
    {title:"Shawn Carlson · A double-blind test of astrology, Nature (1985)",url:"https://www.nature.com/articles/318419a0",note:"An influential controlled test in which astrologers' chart-to-personality matching did not outperform chance under the study conditions. One study is evidence to consider, not a complete review of every astrological practice."},
    {title:"Astronomy Engine · calculation documentation",url:"https://github.com/cosinekitty/astronomy",note:"Open-source astronomical calculation library used by this project for planetary positions. It supports the calculations, not the symbolic interpretations."}
  ];

  const api = {version:"1.0.0",planets,signs,houses,aspects,numerology,topics,sources};
  if (typeof window !== "undefined") window.ASTRO_CURRICULUM = api;
  if (typeof module !== "undefined" && module.exports) module.exports = api;
})();